              className="w-full bg-[#fe9a00] text-black font-black uppercase tracking-widest py-3 rounded hover:bg-white transition-colors shadow-[0_0_20px_rgba(254,154,0,0.3)]"
            >
              Upgrade to Pro
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

